# Build locally with `julia --project=docs docs/make.jl`; the pages are written to docs/build.
# The tutorial pages are generated by Literate from docs/src/tutorials/*.jl at build time
# (docs/src/tutorials/*.md are not tracked). Documenter runs the code of the tutorials;
# test/test_tutorials.jl runs them too, so that they are tested by `Pkg.test()`.

import Documenter
import LinearDecisionRules
import Literate

# The tutorials, in the order of the manual (the names of the files in docs/src/tutorials).
const TUTORIALS = [
    "piecewise_linear",
    "sampled",
    "distributions",
    "advanced_distributions",
    "confidence_mv_normal",
    "multistage",
]

const TUTORIAL_DIR = joinpath(@__DIR__, "src", "tutorials")

# The license header of each file would be rendered as text.
preprocess(content) = replace(content, r"\A# Copyright.*?\n\n"s => "")

for name in TUTORIALS
    file = joinpath(TUTORIAL_DIR, "$name.jl")
    Literate.markdown(file, TUTORIAL_DIR; documenter = true, credit = false, preprocess)
end

pages = [
    "Home" => "index.md",
    "Getting started" => "getting_started.md",
    "Tutorials" => ["tutorials/$name.md" for name in TUTORIALS],
    "API" => [
        "Modelling" => "modelling.md",
        "Results and rules" => "results.md",
        "Simulation" => "simulation.md",
        "Distributions and liftings" => "distributions.md",
        "Internals" => "internals.md",
    ],
]

Documenter.makedocs(;
    sitename = "LinearDecisionRules.jl",
    modules = [LinearDecisionRules],
    repo = Documenter.Remotes.GitHub("bfpc", "LinearDecisionRules.jl"),
    format = Documenter.HTML(; edit_link = "main", prettyurls = get(ENV, "CI", nothing) == "true"),
    pages,
    checkdocs = :all,
)

# Deploy only from CI.
if get(ENV, "CI", nothing) == "true"
    Documenter.deploydocs(;
        repo = "github.com/bfpc/LinearDecisionRules.jl.git",
        push_preview = true,
    )
end
